//! Atomic bitmap run primitives and run discovery.
use super::RtlBitmap;
use core::sync::atomic::{AtomicU32,Ordering};
#[repr(C)] #[derive(Clone,Copy)] pub struct RtlBitmapRun{pub starting_index:u32,pub number_of_bits:u32}
#[inline] unsafe fn bit(b:*const RtlBitmap,i:u32)->bool{!b.is_null()&&i<unsafe{(*b).size_of_bitmap}&&!unsafe{(*b).buffer.is_null()}&&unsafe{*(*b).buffer.add((i/32) as usize)&(1u32<<(i%32))!=0}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_interlocked_set_bit_run(b:*mut RtlBitmap,start:u32,count:u32){if b.is_null()||start.checked_add(count).is_none_or(|e|e>unsafe{(*b).size_of_bitmap})||(count>0&&unsafe{(*b).buffer.is_null()}){return;}for i in start..start+count{let p=unsafe{(*b).buffer.add((i/32) as usize)};unsafe{(&*(p as *const AtomicU32)).fetch_or(1u32<<(i%32),Ordering::SeqCst);}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_interlocked_clear_bit_run(b:*mut RtlBitmap,start:u32,count:u32){if b.is_null()||start.checked_add(count).is_none_or(|e|e>unsafe{(*b).size_of_bitmap})||(count>0&&unsafe{(*b).buffer.is_null()}){return;}for i in start..start+count{let p=unsafe{(*b).buffer.add((i/32) as usize)};unsafe{(&*(p as *const AtomicU32)).fetch_and(!(1u32<<(i%32)),Ordering::SeqCst);}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_interlocked_set_bit_run_ex(b:*mut super::RtlBitmapEx,start:usize,count:usize){if b.is_null()||start.checked_add(count).is_none_or(|e|e>unsafe{(*b).size_of_bitmap})||(count>0&&unsafe{(*b).buffer.is_null()}){return;}for i in start..start+count{let p=unsafe{(*b).buffer.add(i/32)};unsafe{(&*(p as *const AtomicU32)).fetch_or(1u32<<(i%32),Ordering::SeqCst);}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_interlocked_clear_bit_run_ex(b:*mut super::RtlBitmapEx,start:usize,count:usize){if b.is_null()||start.checked_add(count).is_none_or(|e|e>unsafe{(*b).size_of_bitmap})||(count>0&&unsafe{(*b).buffer.is_null()}){return;}for i in start..start+count{let p=unsafe{(*b).buffer.add(i/32)};unsafe{(&*(p as *const AtomicU32)).fetch_and(!(1u32<<(i%32)),Ordering::SeqCst);}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_find_clear_runs(b:*const RtlBitmap,out:*mut RtlBitmapRun,capacity:u32,longest:u8)->u32{if b.is_null()||capacity>0&&out.is_null(){return 0;}let n=unsafe{(*b).size_of_bitmap};if n>0&&unsafe{(*b).buffer.is_null()}{return 0;}let mut found=0u32;let mut i=0u32;while i<n{while i<n&&unsafe{bit(b,i)}{i+=1;}if i==n{break;}let start=i;while i<n&&!unsafe{bit(b,i)}{i+=1;}let run=RtlBitmapRun{starting_index:start,number_of_bits:i-start};if found<capacity{unsafe{*out.add(found as usize)=run;}if longest!=0{let mut j=found as usize;while j>0&&unsafe{(*out.add(j)).number_of_bits>(*out.add(j-1)).number_of_bits}{unsafe{core::ptr::swap(out.add(j),out.add(j-1));}j-=1;}}found+=1;}else if longest!=0&&capacity>0&&run.number_of_bits>unsafe{(*out.add((capacity-1) as usize)).number_of_bits}{unsafe{*out.add((capacity-1) as usize)=run;}let mut j=(capacity-1) as usize;while j>0&&unsafe{(*out.add(j)).number_of_bits>(*out.add(j-1)).number_of_bits}{unsafe{core::ptr::swap(out.add(j),out.add(j-1));}j-=1;}}}found}
